import { useEffect, useRef, useState } from 'preact/hooks';
import { build_photo_properties, type PhotoProperties } from '../../lib/photo-properties';
import {
	MicropubError,
	type MicropubEnvironment,
} from '../../lib/micropub';
import { process_photo, PhotoError } from '../../lib/photo';
import type { StoredToken } from '../../lib/token-store';
import { pkiw_kind_hint, type ComposerConfig } from '../../lib/composer-config';
import { post_or_queue } from '../../lib/post-or-queue';
import { mark_posted_once } from '../../lib/install-prompt-state';
import { useMoreOpen } from '../../lib/composer-prefs';
import {
	peek_share_target,
	consume_share_target,
} from '../../lib/share-target';
import {
	consume_shared_photos,
	type ShareInboxEnvironment,
} from '../../lib/share-inbox';
import { VoiceButton } from '../voice-button';
import { GeocodePicker } from '../geocode-picker';
import { geo_uri, type GeocodeResult } from '../../lib/geocode';
import { Drawer } from '../drawer';
import { draft_text, read_draft, useDraft, type DraftFields } from '../../lib/drafts';
import { DraftStatus } from '../draft-status';
import { ExternalLink } from '../external-link';
import { PublishButton } from '../publish-button';
import { useRevealError } from '../../lib/use-reveal-error';
import {
	MorePanel,
	useMorePanelValues,
	merge_more_values,
} from '../more-panel';

/**
 * Photo mode — single photo or multi-photo gallery.
 *
 * Phase C2b extends C2's single-photo flow to galleries:
 *
 *   1. User picks one or many files via `<input type="file" multiple>`.
 *      Each entry gets a thumbnail, alt-text input, decorative toggle,
 *      remove button, and reorder controls.
 *   2. On submit, every entry runs through process_photo (canvas
 *      downscale + EXIF strip + JPEG re-encode) in sequence.
 *   3. Each processed blob uploads to the Micropub media endpoint;
 *      the resulting URL is collected.
 *   4. A single h-entry posts with `photo[]` (array of media URLs in
 *      gallery order) + `mp-photo-alt[]` (parallel alt-text array).
 *      Single-photo posts still send `photo` and `mp-photo-alt` as
 *      strings for backward compatibility with sites that don't yet
 *      handle the array shape.
 *
 * Auto-format mapping (Phase C5 bridge): 1 photo → image, 2+ →
 * gallery. Same auto-inference; same Post Format taxonomy.
 *
 * Required alt text remains structural (Hard Contract): each entry's
 * Decorative toggle, when checked, submits alt="" for that entry.
 * Otherwise the entry's Submit gates on a non-empty alt string.
 *
 * Reorder: per-entry Move up / Move down buttons (drag-and-drop on
 * mobile is finicky; explicit buttons work everywhere). The buttons
 * disable at array boundaries.
 */

export interface PhotoModeProps {
	token: StoredToken;
	micropubEnv?: MicropubEnvironment;
	composerConfig?: ComposerConfig;
	/** Injectable IndexedDB for the share inbox (tests pass fake-indexeddb). */
	shareInboxEnv?: ShareInboxEnvironment;
}

interface PhotoEntry {
	id: string;
	file: File;
	preview_url: string;
	alt: string;
	decorative: boolean;
	caption: string;
}

type Status =
	| { kind: 'idle' }
	| { kind: 'processing-photo' }
	| { kind: 'discovering-endpoints' }
	| { kind: 'uploading-photo'; current: number; total: number }
	| { kind: 'posting' }
	| { kind: 'posted'; location?: string }
	| { kind: 'queued' }
	| { kind: 'error'; message: string };

let next_id = 1;
const make_id = (): string => `photo-${String(next_id++)}`;

/**
 * What a draft keeps of each photo. The File itself isn't saved, so after a
 * reload the person adds the photos again and these fill in, in order.
 */
interface SavedPhoto {
	alt: string;
	caption: string;
	decorative: boolean;
}

function saved_photos(value: unknown): SavedPhoto[] {
	if (!Array.isArray(value)) return [];
	return value.flatMap((item: unknown) => {
		if (!item || typeof item !== 'object') return [];
		const r = item as Record<string, unknown>;
		return [{ alt: draft_text(r.alt), caption: draft_text(r.caption), decorative: r.decorative === true }];
	});
}

function describe_photo(photo: SavedPhoto): DraftFields {
	return { alt: photo.alt, caption: photo.caption, decorative: photo.decorative };
}

export function PhotoMode({
	token,
	micropubEnv,
	composerConfig,
	shareInboxEnv,
}: PhotoModeProps) {
	// A share wins over an unsent draft, as in NoteMode.
	const [draft] = useState(() =>
		peek_share_target()?.tab === 'photo' ? null : read_draft('photo', token.me),
	);
	const [entries, setEntries] = useState<PhotoEntry[]>([]);
	// Descriptions from the draft still waiting for their photo.
	const [pending_photos, setPendingPhotos] = useState<SavedPhoto[]>(() =>
		saved_photos(draft?.fields.photos),
	);
	const [name, setName] = useState(draft_text(draft?.fields.name));
	const [content, setContent] = useState(draft_text(draft?.fields.content));
	const [picked_location, setPickedLocation] = useState<GeocodeResult | null>(
		null
	);
	const [venue_name, setVenueName] = useState(draft_text(draft?.fields.venue));
	const saved_draft = useDraft({
		mode: 'photo',
		me: token.me,
		fields: {
			name,
			content,
			venue: venue_name,
			photos: [...entries, ...pending_photos].map(describe_photo),
		},
		restored: draft !== null,
	});
	const [status, setStatus] = useState<Status>({ kind: 'idle' });
	const error_ref = useRef<HTMLDivElement>(null);
	useRevealError(error_ref, status.kind === 'error' ? status.message : null);
	const [micropub_endpoint, setMicropubEndpoint] = useState<string | null>(
		null
	);
	const [media_endpoint, setMediaEndpoint] = useState<string | null>(null);
	const [more_values, setMoreValues, resetMoreValues] = useMorePanelValues(composerConfig);
	const [more_open, setMoreOpen] = useMoreOpen();

	const a11y_active =
		composerConfig?.companions['accessibility-checker'] === 'active';

	// Revoke blob URLs on unmount. The previous cleanup captured `entries`
	// at mount (empty array) due to the empty deps array, so unmount
	// cleanup did nothing — ~4 MB of File-backed blob URL leaked per
	// picked photo until the page was unloaded. Tracking entries via a
	// ref lets the cleanup see the current list at unmount time without
	// re-running the effect on every keystroke.
	const entries_ref = useRef(entries);
	entries_ref.current = entries;
	useEffect(() => {
		return (): void => {
			for (const entry of entries_ref.current) {
				URL.revokeObjectURL(entry.preview_url);
			}
		};
	}, []);

	const add_files = (files: File[]): void => {
		if (files.length === 0) return;
		const new_entries: PhotoEntry[] = files.map((file, i) => {
			const saved = pending_photos[i];
			return {
				id: make_id(),
				file,
				preview_url: URL.createObjectURL(file),
				alt: saved?.alt ?? '',
				caption: saved?.caption ?? '',
				decorative: saved?.decorative ?? false,
			};
		});
		setPendingPhotos((prev) => prev.slice(files.length));
		setEntries((prev) => [...prev, ...new_entries]);
	};

	const handle_file_change = (event: Event): void => {
		const input = event.target as HTMLInputElement;
		const picked = input.files;
		if (!picked || picked.length === 0) return;
		add_files(Array.from(picked));
		// Clear the file input so the user can pick the same file again
		// after removing it (browsers cache the previous selection
		// otherwise — picking the same filename does nothing).
		input.value = '';
		if (
			status.kind === 'posted' ||
			status.kind === 'error' ||
			status.kind === 'queued'
		) {
			setStatus({ kind: 'idle' });
		}
	};

	// Share-sheet intake: when this tab is the share destination, claim the
	// stash (caption text) and drain the photos the service worker parked in
	// the share inbox. One-shot — the stash clears on read and the inbox
	// record is deleted once consumed. Runs once on mount, like the other
	// modes' intake; the inbox is only read when the dispatch says it's full.
	useEffect(() => {
		const share = peek_share_target();
		if (!share || share.tab !== 'photo') return;
		consume_share_target();
		if (share.content) setContent(share.content);
		if (share.title) setName(share.title);
		if (!share.sharedPhotos) return;
		let cancelled = false;
		consume_shared_photos(shareInboxEnv)
			.then((inbox) => {
				if (cancelled || !inbox) return;
				add_files(inbox.files);
				if (!share.content && inbox.text) setContent(inbox.text);
				if (!share.title && inbox.title) setName(inbox.title);
			})
			.catch(() => {
				// Inbox unreadable — the Photo tab is open; the user picks the
				// picture again from the library.
			});
		return (): void => {
			cancelled = true;
		};
		// eslint-disable-next-line react-hooks/exhaustive-deps -- mount-only intake, same as NoteMode's consume_share_target_for_note()
	}, []);

	const remove_entry = (id: string): void => {
		setEntries((prev) => {
			const target = prev.find((e) => e.id === id);
			if (target) URL.revokeObjectURL(target.preview_url);
			return prev.filter((e) => e.id !== id);
		});
	};

	const update_entry = (id: string, patch: Partial<PhotoEntry>): void => {
		setEntries((prev) =>
			prev.map((entry) =>
				entry.id === id ? { ...entry, ...patch } : entry
			)
		);
	};

	const move_entry = (id: string, direction: -1 | 1): void => {
		setEntries((prev) => {
			const idx = prev.findIndex((e) => e.id === id);
			const target_idx = idx + direction;
			if (idx === -1 || target_idx < 0 || target_idx >= prev.length)
				return prev;
			const next = [...prev];
			[next[idx], next[target_idx]] = [next[target_idx]!, next[idx]!];
			return next;
		});
	};

	const handle_submit = async (event: Event): Promise<void> => {
		event.preventDefault();
		if (entries.length === 0) return;
		// Each entry must have alt text OR be marked decorative.
		const incomplete = entries.find(
			(entry) => !entry.decorative && entry.alt.trim().length === 0
		);
		if (incomplete) {
			setStatus({
				kind: 'error',
				message:
					"Every photo needs alt text, or mark it decorative. Decorative photos submit empty alt to indicate they're purely visual.",
			});
			return;
		}

		try {
			// Process every photo to a sanitized blob first, so a failing
			// photo doesn't leave half-uploaded media stranded.
			setStatus({ kind: 'processing-photo' });
			const processed_blobs: Blob[] = [];
			for (const entry of entries) {
				const processed = await process_photo(entry.file);
				processed_blobs.push(processed.blob);
			}

			// Alt text and captions pair with the photos by index, so they are
			// built now; post_or_queue adds the uploaded URLs as `photo`, or
			// queues the processed bytes when the network is down.
			const photo_meta: Partial<PhotoProperties> = build_photo_properties(
				entries.map(() => ''),
				entries
			);
			delete photo_meta.photo;
			const trimmed_content = content.trim();
			const trimmed_name = name.trim();
			const trimmed_venue = venue_name.trim();
			const base = {
				...photo_meta,
				...pkiw_kind_hint(composerConfig, 'photo'),
				...(trimmed_name ? { name: trimmed_name } : {}),
				...(trimmed_content ? { content: trimmed_content } : {}),
				...(picked_location
					? {
							location: geo_uri(
								picked_location.lat,
								picked_location.lon
							),
						}
					: {}),
				...(trimmed_venue ? { 'mp-place-name': trimmed_venue } : {}),
			};
			const properties = merge_more_values(base, more_values);
			const result = await post_or_queue(
				{
					source: 'photo',
					me: token.me,
					accessToken: token.accessToken,
					properties,
					photos: processed_blobs.map((blob, i) => ({
						blob,
						filename: `photo-${String(i + 1)}.jpg`,
					})),
					micropubEndpoint: micropub_endpoint,
					mediaEndpoint: media_endpoint,
					onStage: (stage): void =>
						setStatus(
							stage.kind === 'uploading'
								? {
										kind: 'uploading-photo',
										current: stage.current,
										total: stage.total,
									}
								: stage.kind === 'discovering'
									? { kind: 'discovering-endpoints' }
									: { kind: 'posting' }
						),
				},
				micropubEnv
			);
			if (result.micropubEndpoint) setMicropubEndpoint(result.micropubEndpoint);
			if (result.mediaEndpoint) setMediaEndpoint(result.mediaEndpoint);
			saved_draft.discard();
			setPendingPhotos([]);
			if (result.kind === 'queued') {
				setStatus({ kind: 'queued' });
			} else {
				setStatus({
					kind: 'posted',
					...(result.location ? { location: result.location } : {}),
				});
				mark_posted_once();
			}

			// Reset for next post.
			for (const entry of entries) URL.revokeObjectURL(entry.preview_url);
			setEntries([]);
			setName('');
			setContent('');
			resetMoreValues();
			setPickedLocation(null);
			setVenueName('');
		} catch (err) {
			let message: string;
			if (err instanceof PhotoError) {
				message = err.code + ': ' + err.message;
			} else if (err instanceof MicropubError) {
				message = err.code + ': ' + err.message;
			} else if (err instanceof Error) {
				message = err.message;
			} else {
				message = 'Unknown error';
			}
			setStatus({ kind: 'error', message });
		}
	};

	const submitting =
		status.kind === 'processing-photo' ||
		status.kind === 'discovering-endpoints' ||
		status.kind === 'uploading-photo' ||
		status.kind === 'posting';

	const submit_label =
		status.kind === 'processing-photo'
			? 'Preparing photos…'
			: status.kind === 'discovering-endpoints'
				? 'Finding endpoints…'
				: status.kind === 'uploading-photo'
					? `Uploading ${String(status.current)} of ${String(status.total)}…`
					: status.kind === 'posting'
						? 'Posting…'
						: entries.length > 1
							? 'Post gallery'
							: 'Post photo';

	const all_have_alt = entries.every(
		(entry) => entry.decorative || entry.alt.trim().length > 0
	);
	const can_submit = entries.length > 0 && all_have_alt && !submitting;
	const missing: string[] =
		entries.length === 0 ? ['A photo'] : all_have_alt ? [] : ['Alt text for each photo'];

	return (
		<section
			class="outpost-card"
			aria-labelledby="outpost-photo-mode-title"
		>
			<h2 id="outpost-photo-mode-title" class="outpost-card__title">
				{entries.length > 1 ? 'Gallery' : 'Photo'}
			</h2>
			<p class="outpost-card__lede">
				Share a photo or a gallery, with alt text for each image.
			</p>

			<form class="outpost-form-row" onSubmit={handle_submit} novalidate>
				<label class="outpost-label" for="outpost-photo-file">
					{entries.length === 0 ? 'Photo' : 'Add more photos'}
				</label>
				<input
					id="outpost-photo-file"
					class="outpost-input"
					type="file"
					accept="image/jpeg,image/png,image/webp,image/gif,image/avif"
					multiple
					onChange={handle_file_change}
					disabled={submitting}
				/>
				{pending_photos.length > 0 && (
					<p class="outpost-help outpost-draft-photos">
						{pending_photos.length === 1
							? 'Your draft had 1 photo. Add it again and Outpost fills in its alt text and caption.'
							: `Your draft had ${String(pending_photos.length)} photos. Add them again in the same order and Outpost fills in their alt text and captions.`}
					</p>
				)}

				{entries.length > 0 && (
					<ul class="outpost-photo-list">
						{entries.map((entry, index) => (
							<li key={entry.id} class="outpost-photo-list__item">
								<img
									class="outpost-photo-list__thumb"
									src={entry.preview_url}
									alt={entry.alt}
									aria-hidden={!entry.alt}
								/>
								<div class="outpost-photo-list__fields">
									<label
										class="outpost-label"
										for={`outpost-photo-alt-${entry.id}`}
									>
										Alt text{' '}
										{!entry.decorative && (
											<span class="outpost-required">
												(required)
											</span>
										)}
									</label>
									<textarea
										id={`outpost-photo-alt-${entry.id}`}
										class="outpost-textarea"
										rows={2}
										value={entry.alt}
										onInput={(event): void =>
											update_entry(entry.id, {
												alt: (
													event.target as HTMLTextAreaElement
												).value,
											})
										}
										placeholder="Describe what's in the photo for screen readers"
										disabled={
											submitting || entry.decorative
										}
									/>
									<label class="outpost-checkbox">
										<input
											type="checkbox"
											checked={entry.decorative}
											onChange={(event): void =>
												update_entry(entry.id, {
													decorative: (
														event.target as HTMLInputElement
													).checked,
												})
											}
											disabled={submitting}
										/>
										<span>
											Decorative (no alt text needed)
										</span>
									</label>
									<label
										class="outpost-label"
										for={`outpost-photo-caption-${entry.id}`}
									>
										Caption
									</label>
									<textarea
										id={`outpost-photo-caption-${entry.id}`}
										class="outpost-textarea"
										rows={2}
										value={entry.caption}
										onInput={(event): void =>
											update_entry(entry.id, {
												caption: (
													event.target as HTMLTextAreaElement
												).value,
											})
										}
										placeholder="Shown under the photo. Leave empty for none."
										disabled={submitting}
									/>
								</div>
								<div class="outpost-photo-list__actions">
									<button
										type="button"
										class="outpost-button outpost-button--secondary"
										onClick={(): void =>
											move_entry(entry.id, -1)
										}
										disabled={submitting || index === 0}
										aria-label={`Move photo ${String(index + 1)} earlier`}
									>
										<span aria-hidden="true">↑</span>
									</button>
									<button
										type="button"
										class="outpost-button outpost-button--secondary"
										onClick={(): void =>
											move_entry(entry.id, 1)
										}
										disabled={
											submitting ||
											index === entries.length - 1
										}
										aria-label={`Move photo ${String(index + 1)} later`}
									>
										<span aria-hidden="true">↓</span>
									</button>
									<button
										type="button"
										class="outpost-button outpost-button--secondary"
										onClick={(): void =>
											remove_entry(entry.id)
										}
										disabled={submitting}
										aria-label={`Remove photo ${String(index + 1)}`}
									>
										Remove
									</button>
								</div>
							</li>
						))}
					</ul>
				)}

				<label class="outpost-label" for="outpost-photo-name">
					Title (optional)
				</label>
				<input
					id="outpost-photo-name"
					class="outpost-input"
					type="text"
					value={name}
					onInput={(event): void =>
						setName((event.target as HTMLInputElement).value)
					}
					disabled={submitting}
				/>

				<div class="outpost-textarea-row">
					<label class="outpost-label" for="outpost-photo-content">
						Body (optional)
					</label>
					<VoiceButton
						onTranscript={(text): void =>
							setContent((c) =>
								c.length > 0 && !/\s$/.test(c)
									? c + ' ' + text
									: c + text
							)
						}
						disabled={submitting}
					/>
				</div>
				<textarea
					id="outpost-photo-content"
					class="outpost-textarea"
					rows={3}
					value={content}
					onInput={(event): void =>
						setContent((event.target as HTMLTextAreaElement).value)
					}
					disabled={submitting}
				/>

				<GeocodePicker
					idPrefix="outpost-photo"
					accessToken={token.accessToken}
					picked={picked_location}
					onPick={setPickedLocation}
					onClear={(): void => setPickedLocation(null)}
					venueName={venue_name}
					onVenueChange={setVenueName}
					disabled={submitting}
				/>

				<DraftStatus state={saved_draft.state} />

				{composerConfig && (
					<Drawer
						open={more_open}
						onClose={(): void => setMoreOpen(false)}
						title="More options"
						idPrefix="outpost-photo"
					>
						<MorePanel
							token={token}
							composerConfig={composerConfig}
							values={more_values}
							onChange={setMoreValues}
							micropubEndpoint={micropub_endpoint}
							{...(micropubEnv ? { micropubEnv } : {})}
							disabled={submitting}
							idPrefix="outpost-photo"
						/>
					</Drawer>
				)}

				{composerConfig && (
					<div class="outpost-form-actions">
						<button
							class="outpost-button outpost-button--secondary"
							type="button"
							onClick={(): void => setMoreOpen(true)}
							disabled={submitting}
						>
							More options
						</button>
					</div>
				)}

				{/* Persistent live regions stay mounted for iOS VoiceOver. */}
				<div
					ref={error_ref}
					class={`outpost-error${status.kind === 'error' ? '' : ' outpost-error--empty'}`}
					role="alert"
					aria-live="assertive"
				>
					{status.kind === 'error' ? status.message : ''}
				</div>

				<p
					class={`outpost-status${
						status.kind === 'posted' || status.kind === 'queued' ? '' : ' outpost-status--empty'
					}`}
					aria-live="polite"
				>
					{status.kind === 'posted' ? (
						status.location ? (
							<>
								Posted to{' '}
								<ExternalLink href={status.location}>View published post</ExternalLink>
								{a11y_active && (
									<>
										{' · '}
										<ExternalLink href={`${status.location}?edac_view=1`}>
											View accessibility report
										</ExternalLink>
									</>
								)}
							</>
						) : (
							'Posted, but the server did not return a link. Check your site to confirm it published.'
						)
					) : status.kind === 'queued' ? (
						"Saved for later. Outpost will post this when you're back online."
					) : (
						''
					)}
				</p>

				<PublishButton
					idPrefix="outpost-photo"
					label={submit_label}
					disabled={!can_submit}
					missing={missing}
					busy={submitting}
				/>
			</form>
		</section>
	);
}
